import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void; let detach: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); detach = searchService.registerSearchListeners(); });
afterAll(() => { detach(); cleanup(); });

describe("tmp", () => {
  it("works", async () => {
    const t = await createTenant("tmpx", "growth");
    const a = t.actors.owner ?? t.actors.admin ?? t.actors.member;
    const q = (s: string) => searchService.search(a, { orgId: t.org.id, q: s, kinds: [], limit: 25, cursor: null });
    const issues = [];
    for (let i = 0; i < 130; i++) issues.push(await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: `Qqq ${i}` })));
    const c = await commentService.createComment(a, { orgId: t.org.id, issueId: issues[0].id, body: "Qqq comment", parentId: null, mentionedUserIds: [] });
    await issueService.archiveIssue(a, t.org.id, issues[1].id);
    expect((await q("Qqq")).total).toBe(130);
    await projectService.archiveProject(a, { orgId: t.org.id, projectId: t.project.id, archiveIssues: false } as any);
    expect((await q("Qqq")).total).toBe(0);
    await projectService.restoreProject(a, t.org.id, t.project.id);
    expect((await q("Qqq")).total).toBe(130);
    await searchRepo.upsertSearchDocument(t.org.id, "issue", issues[1].id, "Qqq stale", t.project.id);
    const before = await searchRepo.countIndexed(t.org.id);
    await runSearchReindexJob(t.org.id);
    expect((await q("Qqq")).total).toBe(130);
    console.log(before, await searchRepo.countIndexed(t.org.id), c.id);
  });
});
